# fastapi/security/api_key.py:12-20  (fastapi.security.api_key.APIKeyBase.check_api_key)
class APIKeyBase(SecurityBase):
    @staticmethod
    def check_api_key(api_key: Optional[str], auto_error: bool) -> Optional[str]:
        if not api_key:
            if auto_error:
                raise HTTPException(
                    status_code=HTTP_403_FORBIDDEN, detail="Not authenticated"
                )
            return None
        return api_key

# tests/test_security_api_key_cookie_optional.py:17-21  (tests.test_security_api_key_cookie_optional.get_current_user)
def get_current_user(oauth_header: Optional[str] = Security(api_key)):
    if oauth_header is None:
        return None
    user = User(username=oauth_header)
    return user
